                </div>
            </div>
        </div>

        <div className="bg-white w-full max-w-[400px] rounded-[2.5rem] shadow-xl border border-slate-100 p-10 animate-in zoom-in-95 duration-500 relative">

            <div className="mb-8 flex items-center gap-4">
                <div className="bg-indigo-50 p-2.5 rounded-xl text-indigo-600">
                    <KeyRound size={18} strokeWidth={2.5}/>
                </div>
                <h2 className="text-xl font-black text-[#1E293B] tracking-tight uppercase leading-none">Autenticación</h2>
            </div>

            <form onSubmit={handleLogin} className="space-y-8">
                <div className="space-y-3" ref={dropdownRef}>
                    <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2 mb-0.5 ml-1">
                        <UserIcon size={12} strokeWidth={3} className="text-indigo-400"/> Perfil de Usuario
                    </label>
                    <div className="relative">
                        <button
                            type="button"
                            disabled={isAuthenticating}
                            onClick={() => setIsDropdownOpen(!isDropdownOpen)}
                            className={`w-full h-[60px] bg-[#F8FAFC] border-2 ${isDropdownOpen ? 'border-indigo-600 bg-white' : 'border-slate-100 hover:border-slate-200'} rounded-xl px-5 flex items-center justify-between transition-all outline-none disabled:opacity-50`}
                        >
                            {selectedUser ? (
                                <div className="flex items-center gap-3 min-w-0">
                                    <div className="w-8 h-8 rounded-lg bg-indigo-600 text-white flex items-center justify-center font-black text-[9px] shrink-0">
                                        {selectedUser.name.substring(0, 2).toUpperCase()}
                                    </div>
                                    <div className="text-left min-w-0 flex flex-col justify-center">
                                        <div className="text-[14px] font-bold text-slate-900 truncate uppercase tracking-tight leading-none mb-1">{selectedUser.name}</div>
                                        <div className="text-[8px] text-slate-400 font-black uppercase tracking-widest truncate leading-none">{(users.find(u => u.id === selectedUser.id) as any)?.tenant_id ? 'EMPRESA DEMO' : 'GLOBAL'}</div>
                                    </div>
                                </div>
                            ) : (
                                <span className="text-slate-400 text-[10px] font-bold uppercase tracking-widest">Seleccionar Identidad</span>
                            )}
                            <ChevronDown size={18} className={`text-slate-300 transition-transform ${isDropdownOpen ? 'rotate-180 text-indigo-600' : ''}`}/>
                        </button>

                        {isDropdownOpen && (
                            <div className="absolute top-full left-0 right-0 mt-3 bg-white rounded-2xl shadow-2xl border border-slate-100 z-50 max-h-[300px] overflow-y-auto custom-scrollbar animate-in fade-in slide-in-from-top-2">
                                <div className="sticky top-0 bg-slate-50 px-5 py-2 border-b border-slate-100 text-[8px] font-black text-slate-400 uppercase tracking-widest z-10 flex items-center gap-2">
                                    <Building2 size={10} strokeWidth={3}/> Colaboradores Disponibles
                                </div>
                                {users.map(u => (
                                    <UserItem key={u.id} user={u} isSelected={selectedUser?.id === u.id} onSelect={(user) => { setSelectedUser(user); setIsDropdownOpen(false); }} />
                                ))}
                            </div>
                        )}
                    </div>
                </div>

                {selectedUser && (
                    <div className="space-y-6 animate-in slide-in-from-top-4 fade-in duration-300">
                        <div className="space-y-3">
                            <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2 mb-0.5 ml-1">
