import { RequestCard, User, Tenant } from '../types';
import { INITIAL_USERS, INITIAL_REQUESTS } from '../constants';

const SUPABASE_URL = 'https://giwyowsqmgwsaliiduqi.supabase.co';
const SUPABASE_ANON_KEY = 'sb_publishable_Owy6oQHM50c9v1tNp1PCPg_TTSNIger';

const STORE_TENANTS = 'tenants';
const STORE_REQUESTS = 'requests';
const STORE_USERS = 'users';

const DEFAULT_TENANT_ID = '00000000-0000-0000-0000-000000000000';

export interface DbDiagnostic {
    status: 'READY' | 'ERROR' | 'SETUP_REQUIRED';
    message: string;
    sqlSuggestion?: string;
    errorDetails?: any;
}

class DatabaseService {
    private supabase: SupabaseClient;

    constructor() {
        this.supabase = createClient(SUPABASE_URL, SUPABASE_ANON_KEY);
    }

    public async init(): Promise<DbDiagnostic> {
        try {
            const { error: tenantError } = await this.supabase
                .from(STORE_TENANTS)
                .select('*', { count: 'exact', head: true });

            if (tenantError) return this.diagnoseError(tenantError, STORE_TENANTS);

            const { error: userError } = await this.supabase
                .from(STORE_USERS)
                .select('*', { count: 'exact', head: true });

            if (userError) return this.diagnoseError(userError, STORE_USERS);

            await this.seedData();
            return { status: 'READY', message: 'Capa Multi-Tenant Verificada.' };
        } catch (error: any) {
            return { status: 'ERROR', message: error.message || 'Error de red crítico', errorDetails: error };
        }
    }

    private async seedData() {
        // Semilla de Tenant Principal si no existe
        const { count: tCount } = await this.supabase.from(STORE_TENANTS).select('*', { count: 'exact', head: true });
        if (tCount === 0) {
            await this.supabase.from(STORE_TENANTS).insert([{
                id: DEFAULT_TENANT_ID,
                name: 'SISREQ GLOBAL DEMO',
                plan: 'ENTERPRISE',
                createdAt: new Date().toISOString()
            }]);
        }

        const { count: uCount } = await this.supabase.from(STORE_USERS).select('*', { count: 'exact', head: true });
        if (uCount === 0) {
            // IMPORTANTE: Mapear a tenant_id para la base de datos
            const usersWithTenant = INITIAL_USERS.map(u => ({ 
                id: u.id,
                name: u.name,
                email: u.email,
                role: u.role,
                area: u.area,
                password: u.password,
                status: u.status,
                joinedAt: u.joinedAt,
                tenant_id: DEFAULT_TENANT_ID 
            }));
            await this.supabase.from(STORE_USERS).insert(usersWithTenant);
        }

        const { count: rCount } = await this.supabase.from(STORE_REQUESTS).select('*', { count: 'exact', head: true });
        if (rCount === 0) {
            // IMPORTANTE: Mapear a tenant_id para la base de datos
            const reqsWithTenant = INITIAL_REQUESTS.map(r => ({ 
                ...r, 
                tenant_id: DEFAULT_TENANT_ID 
            }));
            // Eliminar la propiedad tenantId (camelCase) antes de insertar en DB
            reqsWithTenant.forEach((r: any) => delete r.tenantId);
            await this.supabase.from(STORE_REQUESTS).insert(reqsWithTenant);
        }
    }

    private diagnoseError(error: any, table: string): DbDiagnostic {
        const msg = error.message || "";
        const code = error.code || "";

        const sqlSchema = `
-- 1. TABLA DE EMPRESAS (TENANTS)
CREATE TABLE IF NOT EXISTS public.tenants (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name text NOT NULL,
  domain text UNIQUE,
  plan text DEFAULT 'BASIC',
  "createdAt" timestamp with time zone DEFAULT now()
);

-- 2. USUARIOS CON AISLAMIENTO
CREATE TABLE IF NOT EXISTS public.users (
  id uuid PRIMARY KEY,
  tenant_id uuid REFERENCES public.tenants(id) ON DELETE CASCADE,
  name text NOT NULL,
  email text,
  role text NOT NULL,
  area text,
  password text,
  status text,
  "joinedAt" timestamp with time zone DEFAULT now(),
  UNIQUE(tenant_id, email)
);

-- 3. REQUERIMIENTOS CON AISLAMIENTO
CREATE TABLE IF NOT EXISTS public.requests (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id uuid REFERENCES public.tenants(id) ON DELETE CASCADE,
  title text NOT NULL,
  detail text,
  requester text,
  area text NOT NULL,
  status text NOT NULL,
  priority text NOT NULL,
  "responsibleHead" text,
  "assignedAnalyst" text,
  logs jsonb DEFAULT '[]'::jsonb,
  "createdAt" timestamp with time zone DEFAULT now(),
  "lastUpdated" timestamp with time zone DEFAULT now(),
  "isDeleted" boolean DEFAULT false,
  "deletedAt" timestamp with time zone,
  "deletedBy" text
);

ALTER TABLE public.tenants ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.users ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.requests ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Tenant Read" ON public.requests FOR SELECT USING (true);
CREATE POLICY "Tenant Write" ON public.requests FOR ALL USING (true);
CREATE POLICY "Tenant Users" ON public.users FOR ALL USING (true);
CREATE POLICY "Tenant Read Global" ON public.tenants FOR SELECT USING (true);
`;

        if (code === '42P01' || msg.includes('does not exist')) {
            return {
                status: 'SETUP_REQUIRED',
                message: `Migración a Multi-Empresa Necesaria`,
                sqlSuggestion: sqlSchema
            };
        }

        return { status: 'ERROR', message: msg, errorDetails: error };
    }

    public async getRequests(tenantId: string): Promise<RequestCard[]> {
        const { data, error } = await this.supabase
            .from(STORE_REQUESTS)
            .select('*')
            .eq('tenant_id', tenantId)
            .order('lastUpdated', { ascending: false });

        if (error) return [];
        // Mapear tenant_id de vuelta a tenantId para el frontend
        return (data || []).map(r => ({
            ...r,
            tenantId: r.tenant_id
        })) as RequestCard[];
    }

    public async saveRequest(req: RequestCard): Promise<void> {
        const { tenantId, ...rest } = req;
        const dbReady = {
            ...rest,
            tenant_id: tenantId
        };
        const { error } = await this.supabase.from(STORE_REQUESTS).upsert(dbReady);
        if (error) throw new Error(`DB_WRITE_ERROR: ${error.message}`);
    }

    public async getUsers(tenantId?: string): Promise<User[]> {
        let query = this.supabase.from(STORE_USERS).select('*');
        if (tenantId) query = query.eq('tenant_id', tenantId);

        const { data, error } = await query;
        if (error) return [];

        return (data || []).map(u => ({ 
            ...u, 
            tenantId: u.tenant_id 
        })) as User[];
    }

    public async validateUser(email: string, pass: string): Promise<User | null> {
        const { data, error } = await this.supabase
            .from(STORE_USERS)
            .select('*')
            .eq('email', email)
            .eq('password', pass)
            .maybeSingle();

        if (error || !data) return null;

        const { password, tenant_id, ...safeUser } = data;
        return { 
            ...safeUser, 
            tenantId: tenant_id 
        } as User;
    }

    public async getTenant(id: string): Promise<Tenant | null> {
        const { data, error } = await this.supabase
            .from(STORE_TENANTS)
            .select('*')
            .eq('id', id)
            .maybeSingle();
        return error ? null : data as Tenant;
    }
}

