  markNotificationAsRead: (id: string) => void;
  clearNotifications: () => void;

  canUserTransition: (request: RequestCard, targetStatus: Status) => { allowed: boolean; reason?: string };
  canUserSeeRequest: (request: RequestCard) => boolean;
  isActionable: (request: RequestCard) => boolean;
}

const SisreqContext = createContext<SisreqContextType | undefined>(undefined);

const DEFAULT_SETTINGS: NotificationSettings = {
  enabled: true,
  sounds: false,
  newRequests: true,
  statusChanges: true,
  returns: true,
  assignments: true,
  auditAlerts: true
};

const genUUID = () => {
    if (typeof crypto !== 'undefined' && crypto.randomUUID) {
        return crypto.randomUUID();
    }
    return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
        const r = (Math.random() * 16) | 0;
        const v = c === 'x' ? r : (r & 0x3) | 0x8;
        return v.toString(16);
    });
};

const WORKFLOW_MATRIX: TransitionRule[] = [
  { from: Status.RECIBIDO, to: Status.DERIVACION, allowedRoles: [UserRole.ADMIN, UserRole.SUPERADMIN] },
  { from: Status.DERIVACION, to: Status.EJECUCION, allowedRoles: [UserRole.HEAD, UserRole.SUPERADMIN, UserRole.ADMIN], requiresAnalyst: true, checkAreaJurisdiction: true },
  { from: Status.EJECUCION, to: Status.FINALIZADO, allowedRoles: [UserRole.ANALYST, UserRole.HEAD, UserRole.SUPERADMIN], checkAreaJurisdiction: true }, 
  { from: Status.RECIBIDO, to: Status.FINALIZADO, allowedRoles: [UserRole.SUPERADMIN] }, 
  { from: Status.DERIVACION, to: Status.FINALIZADO, allowedRoles: [UserRole.SUPERADMIN, UserRole.HEAD], checkAreaJurisdiction: true }, 
  { from: Status.FINALIZADO, to: Status.RECIBIDO, allowedRoles: [UserRole.SUPERADMIN] },
  { from: Status.EJECUCION, to: Status.RECIBIDO, allowedRoles: [UserRole.HEAD, UserRole.ADMIN, UserRole.SUPERADMIN], checkAreaJurisdiction: true },
  { from: Status.DERIVACION, to: Status.RECIBIDO, allowedRoles: [UserRole.HEAD, UserRole.ADMIN, UserRole.SUPERADMIN], checkAreaJurisdiction: true }
];

export const SisreqProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [users, setUsers] = useState<User[]>([]);
  const [requests, setRequests] = useState<RequestCard[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [notificationSettings, setNotificationSettings] = useState<NotificationSettings>(() => {
    const saved = localStorage.getItem('sisreq_notification_settings');
    return saved ? JSON.parse(saved) : DEFAULT_SETTINGS;
  });
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [currentTenant, setCurrentTenant] = useState<Tenant | null>(null);
  const [activeRole, setActiveRole] = useState<UserRole | null>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('work');
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [initError, setInitError] = useState<string | null>(null);
  const [dbDiagnostic, setDbDiagnostic] = useState<DbDiagnostic | null>(null);
  const [globalFilterArea, setGlobalFilterArea] = useState<Area | 'ALL'>('ALL');
  const [selectedRequestId, setSelectedRequestId] = useState<string | null>(null);

  const loadData = useCallback(async (tenantId: string) => {
      const [loadedUsers, loadedRequests] = await Promise.all([
        db.getUsers(tenantId),
        db.getRequests(tenantId)
      ]);
      setUsers(loadedUsers);
      setRequests(loadedRequests.sort((a, b) => 
        new Date(b.lastUpdated || b.createdAt).getTime() - new Date(a.lastUpdated || a.createdAt).getTime()
      ));
  }, []);

  useEffect(() => {
    const initializeSystem = async () => {
      try {
        const diag = await db.init();
        setDbDiagnostic(diag);
        if (diag.status === 'READY') {
            // Cargar usuarios globales para permitir login (solo en demo)
            const allUsers = await db.getUsers();
            setUsers(allUsers);
        }
      } catch (error: any) {
        setInitError(`Fallo de Inicialización: ${error.message}`);
      } finally {
        setIsLoading(false);
      }
    };
    initializeSystem();
  }, []);

  const login = async (email: string, pass: string): Promise<boolean> => {
    try {
        const user = await db.validateUser(email, pass);
        if (user) {
            const tenant = await db.getTenant(user.tenantId);
            setCurrentUser(user);
            setCurrentTenant(tenant);
            setActiveRole(user.role);
            setIsAuthenticated(true);
            setGlobalFilterArea(user.role === UserRole.ADMIN || user.role === UserRole.SUPERADMIN ? 'ALL' : (user.area as Area));

            await loadData(user.tenantId);

            addNotification('INFO', 'Acceso Corporativo', `Conectado a ${tenant?.name || 'Sistema'}. Bienvenido(a), ${user.name}.`);
            return true;
        }
        return false;
    } catch (e) {
        console.error("Login Error:", e);
        return false;
    }
  };

  const logout = () => {
    setIsAuthenticated(false);
    setCurrentUser(null);
    setCurrentTenant(null);
    setActiveRole(null);
    setSelectedRequestId(null);
    setNotifications([]);
    setRequests([]);
    // Recargar usuarios globales para volver a mostrar el login dropdown
    db.getUsers().then(setUsers);
  };

  const addNotification = useCallback((type: NotificationType, title: string, message: string, requestId?: string) => {
    if (!notificationSettings.enabled || !currentUser) return;

    const newNotif: Notification = {
      id: genUUID(),
      tenantId: currentUser.tenantId,
      type,
      title,
      message,
      timestamp: new Date().toISOString(),
      isRead: false,
      requestId
    };
    setNotifications(prev => [newNotif, ...prev].slice(0, 50));
  }, [notificationSettings, currentUser]);

  const canUserSeeRequest = useCallback((req: RequestCard): boolean => {
    if (!currentUser || !activeRole) return false;
    if (req.tenantId !== currentUser.tenantId) return false;

    if (req.isDeleted && activeRole !== UserRole.SUPERADMIN) return false; 
    if (activeRole === UserRole.SUPERADMIN || activeRole === UserRole.ADMIN) return true;
    const isSameArea = req.area === currentUser.area;
    const isOutOfCentral = req.status !== Status.RECIBIDO;
    return isSameArea && isOutOfCentral;
  }, [currentUser, activeRole]);

  const addRequest = async (title: string, detail: string, area: Area, priority: Priority, requester: string) => {
    if (!currentUser) return;
    const now = new Date().toISOString();
    const initialStatus = (activeRole === UserRole.ADMIN || activeRole === UserRole.SUPERADMIN) ? Status.RECIBIDO : Status.DERIVACION;
    const newReq: RequestCard = {
      id: genUUID(),
      tenantId: currentUser.tenantId,
      title, detail, area, status: initialStatus, priority, requester,
      responsibleHead: AREA_HEADS[area], createdAt: now, lastUpdated: now,
      logs: [{
        id: genUUID(),
        timestamp: now,
        message: `APERTURA CORPORATIVA: Registro inicializado en fase ${initialStatus}`,
        actor: currentUser.name,
        role: activeRole || UserRole.ANALYST
      }]
    };
    await db.saveRequest(newReq);
    setRequests(prev => [newReq, ...prev]);
    addNotification('SUCCESS', 'Nuevo Expediente', `Ticket registrado: ${title}`, newReq.id);
  };

  const updateStatus = async (id: string, newStatus: Status) => {
    const req = requests.find(r => r.id === id);
    if (!req || !currentUser) return;

    const now = new Date().toISOString();
    const updated = { 
        ...req, 
        status: newStatus, 
        lastUpdated: now, 
        logs: [...req.logs, {
            id: genUUID(),
            timestamp: now,
            message: `TRANSICIÓN: Cambio de fase operativa a ${newStatus}`,
            actor: currentUser.name,
            role: activeRole || UserRole.ANALYST
        }] 
    };
    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const addUser = async (name: string, email: string, role: UserRole, pass: string, area?: Area) => {
    if (!currentUser) return;
    const newUser: User = { 
        id: genUUID(), 
        tenantId: currentUser.tenantId, 
        name, email, role, area, password: pass, status: 'ACTIVE', joinedAt: new Date().toISOString() 
    };
    // await db.saveUser(newUser);
    addNotification('SUCCESS', 'Nuevo Usuario', `Colaborador creado en ${currentTenant?.name}: ${name}`);
    await loadData(currentUser.tenantId);
  };

  const canUserTransition = useCallback((req: RequestCard, target: Status): { allowed: boolean; reason?: string } => {
    if (!currentUser || !activeRole) return { allowed: false, reason: 'Sesión inactiva.' };
    const rule = WORKFLOW_MATRIX.find(r => r.from === req.status && r.to === target);
    if (!rule) return { allowed: false, reason: 'Flujo operativo no permitido.' };
    return { allowed: true };
  }, [currentUser, activeRole]);

  const isActionable = useCallback((req: RequestCard): boolean => {
    if (!activeRole || req.isDeleted) return false;
    return true;
  }, [activeRole]);

  return (
    <SisreqContext.Provider value={{
      currentUser, currentTenant, users, requests, notifications, notificationSettings, isAuthenticated, isLoading, initError, dbDiagnostic, activeRole, viewMode, globalFilterArea, selectedRequestId,
      login, logout, setActiveRole: (r) => setActiveRole(r), switchHybridRole: () => {}, setViewMode: (m) => setViewMode(m), addUser, updateUser: async (u) => {},
      setSelectedRequestId, setGlobalFilterArea, addRequest, updateStatus, returnRequest: async (id, r) => {}, assignAnalyst: async (id, n) => {}, addLog: async (id, m) => {}, updateRequestDetails: async (id, t, d) => {}, deleteRequest: async (id) => {},
      addNotification, updateNotificationSettings: (s) => setNotificationSettings(prev => ({...prev, ...s})), markNotificationAsRead: (id) => {}, clearNotifications: () => {},
      canUserTransition, canUserSeeRequest, isActionable
    }}>
      {children}
    </SisreqContext.Provider>
  );
};

export const useSisreq = () => {
  const context = useContext(SisreqContext);
  if (!context) throw new Error('useSisreq debe usarse dentro de SisreqProvider');
  return context;
};

import React, { useState, useRef, useEffect } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { UserRole, User } from '../types';
import { LayoutDashboard, User as UserIcon, Shield, Briefcase, KeyRound, LogIn, ChevronDown, Check, Sparkles, AlertCircle, Building2 } from 'lucide-react';

const getRoleLabel = (role: UserRole) => {
  switch (role) {
      case UserRole.SUPERADMIN: return 'Control Maestro';
      case UserRole.ADMIN: return 'Administración Central';
      case UserRole.HEAD: return 'Jefaturas de Área';
      default: return 'Cuerpo Analista';
  }
};

interface UserItemProps {
  user: User;
  isSelected: boolean;
  onSelect: (user: User) => void;
}

const UserItem: React.FC<UserItemProps> = ({ user, isSelected, onSelect }) => (
    <button 
      type="button"
      onClick={() => onSelect(user)}
      className="w-full flex items-center gap-3 p-3 hover:bg-indigo-50/50 transition-all text-left group border-b border-slate-50 last:border-0"
    >
      <div className={`w-9 h-9 rounded-lg flex items-center justify-center font-black text-[10px] transition-all shadow-sm shrink-0 ${
          user.role === UserRole.SUPERADMIN ? 'bg-slate-900 text-white' :
          user.role === UserRole.ADMIN ? 'bg-red-50 text-red-600 group-hover:bg-red-100' :
          user.role === UserRole.HEAD ? 'bg-indigo-50 text-indigo-600 group-hover:bg-indigo-100' :
          'bg-slate-100 text-slate-500 group-hover:bg-slate-200'
      }`}>
          {user.name.substring(0, 2).toUpperCase()}
      </div>
      <div className="flex-1 min-w-0 flex flex-col justify-center">
          <div className="text-[12px] font-bold text-slate-800 group-hover:text-indigo-600 truncate uppercase tracking-tight leading-none mb-1">{user.name}</div>
          <div className="text-[8px] text-slate-400 font-black uppercase tracking-widest truncate leading-none">{user.area || getRoleLabel(user.role)}</div>
      </div>
      {isSelected && <div className="bg-indigo-600 p-1 rounded-full text-white shrink-0"><Check size={12} strokeWidth={3}/></div>}
    </button>
);

export const LoginPage: React.FC = () => {
  const { login, users } = useSisreq();
  const [selectedUser, setSelectedUser] = useState<User | null>(null);
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const [isAuthenticating, setIsAuthenticating] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedUser) return;
    setIsAuthenticating(true);
    setError('');

    try {
        const success = await login(selectedUser.email, password);
        if (!success) {
            setError('Credenciales corporativas no válidas.');
            setPassword('');
        }
    } catch (err) {
        setError('Error de conexión con el servidor de identidades.');
    } finally {
        setIsAuthenticating(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#F8FAFC] flex flex-col items-center justify-center p-6">

        <div className="mb-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
            <div className="inline-flex items-center gap-5 bg-white px-6 py-4 rounded-3xl shadow-sm border border-slate-100">
                <div className="bg-slate-900 p-3 rounded-xl shadow-md">
                    <Building2 className="text-white" size={24} strokeWidth={2.5}/>
                </div>
                <div className="text-left pr-2">
                    <h1 className="text-2xl font-black tracking-tighter text-[#1E293B] leading-none uppercase">SISREQ CLOUD</h1>
                    <p className="text-[8px] font-black text-indigo-500 uppercase tracking-widest mt-1.5 opacity-80">Plataforma Multi-Empresa</p>
                </div>
            </div>
        </div>

        <div className="bg-white w-full max-w-[400px] rounded-[2.5rem] shadow-xl border border-slate-100 p-10 animate-in zoom-in-95 duration-500 relative">

            <div className="mb-8 flex items-center gap-4">
                <div className="bg-indigo-50 p-2.5 rounded-xl text-indigo-600">
                    <KeyRound size={18} strokeWidth={2.5}/>
                </div>
                <h2 className="text-xl font-black text-[#1E293B] tracking-tight uppercase leading-none">Autenticación</h2>
            </div>

            <form onSubmit={handleLogin} className="space-y-8">
                <div className="space-y-3" ref={dropdownRef}>
                    <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2 mb-0.5 ml-1">
                        <UserIcon size={12} strokeWidth={3} className="text-indigo-400"/> Perfil de Usuario
                    </label>
                    <div className="relative">
                        <button
                            type="button"
                            disabled={isAuthenticating}
                            onClick={() => setIsDropdownOpen(!isDropdownOpen)}
                            className={`w-full h-[60px] bg-[#F8FAFC] border-2 ${isDropdownOpen ? 'border-indigo-600 bg-white' : 'border-slate-100 hover:border-slate-200'} rounded-xl px-5 flex items-center justify-between transition-all outline-none disabled:opacity-50`}
                        >
                            {selectedUser ? (
                                <div className="flex items-center gap-3 min-w-0">
                                    <div className="w-8 h-8 rounded-lg bg-indigo-600 text-white flex items-center justify-center font-black text-[9px] shrink-0">
                                        {selectedUser.name.substring(0, 2).toUpperCase()}
                                    </div>
                                    <div className="text-left min-w-0 flex flex-col justify-center">
                                        <div className="text-[14px] font-bold text-slate-900 truncate uppercase tracking-tight leading-none mb-1">{selectedUser.name}</div>
                                        <div className="text-[8px] text-slate-400 font-black uppercase tracking-widest truncate leading-none">{selectedUser.tenantId === '00000000-0000-0000-0000-000000000000' ? 'SISREQ GLOBAL DEMO' : 'EMPRESA CORPORATIVA'}</div>
                                    </div>
                                </div>
                            ) : (
                                <span className="text-slate-400 text-[10px] font-bold uppercase tracking-widest">Seleccionar Identidad</span>
                            )}
                            <ChevronDown size={18} className={`text-slate-300 transition-transform ${isDropdownOpen ? 'rotate-180 text-indigo-600' : ''}`}/>
                        </button>

                        {isDropdownOpen && (
                            <div className="absolute top-full left-0 right-0 mt-3 bg-white rounded-2xl shadow-2xl border border-slate-100 z-50 max-h-[300px] overflow-y-auto custom-scrollbar animate-in fade-in slide-in-from-top-2">
                                <div className="sticky top-0 bg-slate-50 px-5 py-2 border-b border-slate-100 text-[8px] font-black text-slate-400 uppercase tracking-widest z-10 flex items-center gap-2">
                                    <Building2 size={10} strokeWidth={3}/> Colaboradores Disponibles
                                </div>
                                {users.map(u => (
                                    <UserItem key={u.id} user={u} isSelected={selectedUser?.id === u.id} onSelect={(user) => { setSelectedUser(user); setIsDropdownOpen(false); }} />
                                ))}
                                {users.length === 0 && (
                                    <div className="p-4 text-center text-[10px] text-slate-400 uppercase font-black">Cargando base de datos...</div>
                                )}
                            </div>
                        )}
                    </div>
                </div>

                {selectedUser && (
                    <div className="space-y-6 animate-in slide-in-from-top-4 fade-in duration-300">
                        <div className="space-y-3">
                            <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2 mb-0.5 ml-1">
                                <KeyRound size={12} strokeWidth={3} className="text-indigo-400"/> Firma Corporativa
                            </label>
                            <input 
                                type="password" 
                                autoFocus
                                disabled={isAuthenticating}
                                value={password}
                                onChange={(e) => setPassword(e.target.value)}
                                className="w-full h-[60px] bg-[#F8FAFC] border-2 border-slate-100 rounded-xl focus:border-indigo-600 focus:bg-white outline-none transition-all font-black text-center text-xl tracking-[0.5em] shadow-inner"
                                placeholder="••••"
                            />
                        </div>

                        {error && (
                            <div className="bg-red-50 text-red-600 p-4 rounded-xl text-[10px] font-black uppercase tracking-widest flex items-center gap-3 border border-red-100">
                                <AlertCircle size={16} strokeWidth={3}/> {error}
                            </div>
                        )}

                        <button 
                            type="submit"
                            disabled={isAuthenticating}
                            className={`w-full h-[60px] ${isAuthenticating ? 'bg-slate-400' : 'bg-slate-900 hover:bg-black'} text-white font-black rounded-xl shadow-lg transition-all active:scale-95 flex items-center justify-center gap-3 uppercase text-[10px] tracking-widest`}
                        >
                            <LogIn size={20} strokeWidth={2.5}/> 
                            <span>{isAuthenticating ? 'Conectando...' : 'Entrar al Ecosistema'}</span>
                        </button>
                    </div>
                )}
            </form>
        </div>
    </div>
  );
};
